-- 패키지 인터페이스 선언
CREATE OR REPLACE PACKAGE MY_PKG AS
    FUNCTION ADD_ONE(N NUMBER) RETURN NUMBER;
END;
/

-- 함수 구현
CREATE OR REPLACE PACKAGE BODY MY_PKG AS
    FUNCTION ADD_ONE(N NUMBER)
    RETURN NUMBER IS
    BEGIN
        RETURN N + 1;
    END;
END;
/

SELECT NAME
FROM TEST
WHERE ROWNUM = 3;

SELECT NAME
FROM (
    SELECT NAME, ROWNUM AS RNUM
    FROM TEST
)
WHERE RNUM = 3;
